begin;
create table public.checklist_category_settings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,category_key text not null check(category_key in('infrastructure','electrical','water','fire','custom')),enabled boolean not null default false,frequency text not null default 'Hàng ngày' check(frequency in('Hàng ngày','Hàng tuần','Hàng tháng','Hàng quý','Hàng năm','Linh hoạt')),execution_time text not null default '09:00' check(execution_time~'^([01][0-9]|2[0-3]):[0-5][0-9]$'),assignee text not null default 'Admin',updated_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,category_key));
create table public.checklist_definitions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,title text not null check(char_length(btrim(title)) between 1 and 180),target_kind text not null check(target_kind in('equipment','system')),target_label text not null check(char_length(btrim(target_label)) between 1 and 240),target_asset_id uuid,category_key text not null check(category_key in('infrastructure','electrical','water','fire','equipment','custom')),frequency text not null check(frequency in('Hàng ngày','Hàng tuần','Hàng tháng','Hàng quý','Hàng năm','Linh hoạt')),execution_time text not null default '09:00' check(execution_time~'^([01][0-9]|2[0-3]):[0-5][0-9]$'),assignee text not null default 'Admin',enabled boolean not null default true,questions jsonb not null default '[]'::jsonb check(jsonb_typeof(questions)='array'),source text not null default 'custom' check(source in('starter','equipment-suggestion','custom')),version integer not null default 1 check(version>0),schedule_started_at timestamptz not null default now(),last_completed_at timestamptz,created_by uuid not null references auth.users(id) on delete restrict,updated_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),foreign key(organization_id,target_asset_id) references public.assets(organization_id,id) on delete restrict,check(target_kind<>'system' or jsonb_array_length(questions)>=5),check(target_kind<>'equipment' or target_asset_id is not null));
create index checklist_definitions_org_enabled_idx on public.checklist_definitions(organization_id,enabled,category_key);
create table public.checklist_definition_versions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,definition_id uuid not null,version integer not null check(version>0),snapshot jsonb not null check(jsonb_typeof(snapshot)='object'),changed_by uuid not null references auth.users(id) on delete restrict,changed_at timestamptz not null default now(),unique(organization_id,definition_id,version),foreign key(organization_id,definition_id) references public.checklist_definitions(organization_id,id) on delete restrict);
create table public.checklist_tasks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,definition_id uuid not null,due_at timestamptz not null,due_date date not null,status text not null default 'Chờ thực hiện' check(status in('Chờ thực hiện','Đang thực hiện','Hoàn thành','Không Checklist')),assignee text not null default 'Admin',claimed_by_user_id uuid references auth.users(id) on delete set null,claimed_at timestamptz,definition_snapshot jsonb not null check(jsonb_typeof(definition_snapshot)='object'),completed_at timestamptz,run_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,definition_id,due_date),unique(organization_id,id),foreign key(organization_id,definition_id) references public.checklist_definitions(organization_id,id) on delete restrict);
create index checklist_tasks_org_due_idx on public.checklist_tasks(organization_id,due_at,status);
create table public.checklist_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,definition_id uuid not null,task_id uuid,checklist_title text not null,category_label text not null,target_label text not null,frequency text not null,answers jsonb not null check(jsonb_typeof(answers)='array'),outcome text not null check(outcome in('Đạt','Không đạt','Bỏ qua')),inspector text not null,inspector_user_id uuid not null references auth.users(id) on delete restrict,completed_at timestamptz not null default now(),repair_request_created boolean not null default false,no_repair_reason text,checklist_snapshot jsonb not null check(jsonb_typeof(checklist_snapshot)='array'),created_at timestamptz not null default now(),unique(organization_id,id),foreign key(organization_id,definition_id) references public.checklist_definitions(organization_id,id) on delete restrict,foreign key(organization_id,task_id) references public.checklist_tasks(organization_id,id) on delete restrict);
create index checklist_runs_org_completed_idx on public.checklist_runs(organization_id,completed_at desc);
alter table public.checklist_tasks add constraint checklist_tasks_run_fk foreign key(organization_id,run_id) references public.checklist_runs(organization_id,id) on delete restrict;
create table public.checklist_task_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,task_id uuid not null,event_type text not null check(event_type in('Nhận việc','Trả lại nhóm','Hoàn thành','Hủy thực hiện')),actor_user_id uuid not null references auth.users(id) on delete restrict,actor_label text not null,occurred_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb check(jsonb_typeof(metadata)='object'),foreign key(organization_id,task_id) references public.checklist_tasks(organization_id,id) on delete restrict);
create index checklist_task_events_org_task_idx on public.checklist_task_events(organization_id,task_id,occurred_at);
alter table public.checklist_category_settings enable row level security;
alter table public.checklist_definitions enable row level security;
alter table public.checklist_definition_versions enable row level security;
alter table public.checklist_tasks enable row level security;
alter table public.checklist_runs enable row level security;
alter table public.checklist_task_events enable row level security;
grant select,insert,update,delete on public.checklist_category_settings to authenticated;
grant select,insert,update,delete on public.checklist_definitions to authenticated;
grant select on public.checklist_definition_versions,public.checklist_tasks,public.checklist_runs,public.checklist_task_events to authenticated;
create policy checklist_category_settings_select on public.checklist_category_settings for select to authenticated using(private.has_org_permission(organization_id,'checklist.view'));
create policy checklist_category_settings_manage on public.checklist_category_settings for all to authenticated using(private.has_org_permission(organization_id,'checklist.template.manage')) with check(private.has_org_permission(organization_id,'checklist.template.manage'));
create policy checklist_definitions_select on public.checklist_definitions for select to authenticated using(private.has_org_permission(organization_id,'checklist.view'));
create policy checklist_definitions_manage on public.checklist_definitions for all to authenticated using(private.has_org_permission(organization_id,'checklist.template.manage')) with check(private.has_org_permission(organization_id,'checklist.template.manage'));
create policy checklist_definition_versions_select on public.checklist_definition_versions for select to authenticated using(private.has_org_permission(organization_id,'checklist.view'));
create policy checklist_tasks_select on public.checklist_tasks for select to authenticated using(private.has_org_permission(organization_id,'checklist.view'));
create policy checklist_runs_select on public.checklist_runs for select to authenticated using(private.has_org_permission(organization_id,'checklist.view'));
create policy checklist_task_events_select on public.checklist_task_events for select to authenticated using(private.has_org_permission(organization_id,'checklist.view'));
create or replace function private.claim_checklist_task(p_organization_id uuid,p_task_id uuid) returns jsonb language plpgsql security definer set search_path='' set row_security=off as $$
declare v_user uuid:=auth.uid();v_task public.checklist_tasks;
begin
if v_user is null or not private.has_org_permission(p_organization_id,'checklist.result.create') then raise exception 'Không có quyền thực hiện Checklist.' using errcode='42501';end if;
select * into v_task from public.checklist_tasks where organization_id=p_organization_id and id=p_task_id for update;
if not found then raise exception 'Không tìm thấy lượt Checklist.' using errcode='P0002';end if;
if v_task.status<>'Chờ thực hiện' then raise exception 'Lượt Checklist đã được nhận hoặc không còn khả dụng.' using errcode='40001';end if;
if v_task.due_at>now() or now()-v_task.due_at>=interval '24 hours' then raise exception 'Lượt Checklist chưa đến hạn hoặc đã hết thời gian thực hiện.' using errcode='55000';end if;
update public.checklist_tasks set status='Đang thực hiện',claimed_by_user_id=v_user,claimed_at=clock_timestamp(),updated_at=clock_timestamp() where organization_id=p_organization_id and id=p_task_id returning * into v_task;
insert into public.checklist_task_events(organization_id,task_id,event_type,actor_user_id,actor_label) values(p_organization_id,p_task_id,'Nhận việc',v_user,coalesce((select display_name from public.profiles where id=v_user),'Admin'));
return to_jsonb(v_task);end;$$;
create or replace function private.complete_checklist_task(p_organization_id uuid,p_task_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' set row_security=off as $$
declare v_user uuid:=auth.uid();v_task public.checklist_tasks;v_run_id uuid:=gen_random_uuid();v_answers jsonb;v_failed boolean;v_passed boolean;v_outcome text;v_inspector text;
begin
if v_user is null or not private.has_org_permission(p_organization_id,'checklist.result.create') then raise exception 'Không có quyền hoàn thành Checklist.' using errcode='42501';end if;
select * into v_task from public.checklist_tasks where organization_id=p_organization_id and id=p_task_id for update;
if not found or v_task.status<>'Đang thực hiện' or v_task.claimed_by_user_id<>v_user then raise exception 'Bạn không còn quyền nhận lượt Checklist này.' using errcode='42501';end if;
if now()-v_task.due_at>=interval '24 hours' then raise exception 'Lượt Checklist đã quá thời gian thực hiện.' using errcode='55000';end if;
v_answers:=p_payload->'answers';
if jsonb_typeof(v_answers)<>'array' or jsonb_array_length(v_answers)<>jsonb_array_length(v_task.definition_snapshot->'questions') or exists(select 1 from jsonb_array_elements(v_answers) a where coalesce(a->>'result','') not in('Đạt','Không đạt','Bỏ qua')) then raise exception 'Kết quả Checklist chưa đầy đủ hoặc không hợp lệ.' using errcode='22023';end if;
select exists(select 1 from jsonb_array_elements(v_answers) a where a->>'result'='Không đạt'),exists(select 1 from jsonb_array_elements(v_answers) a where a->>'result'='Đạt') into v_failed,v_passed;
v_outcome:=case when v_failed then 'Không đạt' when v_passed then 'Đạt' else 'Bỏ qua' end;
v_inspector:=coalesce(nullif(btrim(p_payload->>'inspector'),''),(select display_name from public.profiles where id=v_user),'Admin');
if v_failed and coalesce((p_payload->>'repair_request_created')::boolean,false)=false and nullif(btrim(p_payload->>'no_repair_reason'),'') is null then raise exception 'Cần ghi lý do chưa tạo Phiếu yêu cầu sửa chữa.' using errcode='22023';end if;
insert into public.checklist_runs(id,organization_id,definition_id,task_id,checklist_title,category_label,target_label,frequency,answers,outcome,inspector,inspector_user_id,completed_at,repair_request_created,no_repair_reason,checklist_snapshot)
values(v_run_id,p_organization_id,v_task.definition_id,p_task_id,coalesce(p_payload->>'checklist_title',''),coalesce(p_payload->>'category_label',''),coalesce(p_payload->>'target_label',''),coalesce(p_payload->>'frequency',''),v_answers,v_outcome,v_inspector,v_user,clock_timestamp(),coalesce((p_payload->>'repair_request_created')::boolean,false),nullif(btrim(p_payload->>'no_repair_reason'),''),coalesce(p_payload->'checklist_snapshot','[]'::jsonb));
update public.checklist_tasks set status='Hoàn thành',completed_at=clock_timestamp(),run_id=v_run_id,updated_at=clock_timestamp() where organization_id=p_organization_id and id=p_task_id;
update public.checklist_definitions set last_completed_at=clock_timestamp(),updated_at=clock_timestamp() where organization_id=p_organization_id and id=v_task.definition_id;
insert into public.checklist_task_events(organization_id,task_id,event_type,actor_user_id,actor_label) values(p_organization_id,p_task_id,'Hoàn thành',v_user,v_inspector);
return jsonb_build_object('run_id',v_run_id,'outcome',v_outcome,'completed_at',clock_timestamp());end;$$;
revoke all on function private.claim_checklist_task(uuid,uuid) from public,anon;
revoke all on function private.complete_checklist_task(uuid,uuid,jsonb) from public,anon;
grant usage on schema private to authenticated;
grant execute on function private.claim_checklist_task(uuid,uuid) to authenticated;
grant execute on function private.complete_checklist_task(uuid,uuid,jsonb) to authenticated;
commit;